def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(ch < "0" or ch > "9" for ch in token):
            return None
        # Parse in chunks to avoid Python's decimal string conversion limit.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]
        success = False

        if verb == "undo" and len(parts) == 1:
            if history:
                record = history.pop()
                kind = record[0]
                if kind == "open":
                    account = record[1]
                    del balances[account]
                    frozen.discard(account)
                elif kind == "balance":
                    account, old_balance = record[1:]
                    balances[account] = old_balance
                elif kind == "transfer":
                    source, target, source_balance, target_balance = record[1:]
                    balances[source] = source_balance
                    balances[target] = target_balance
                elif kind == "freeze":
                    frozen.discard(record[1])
                else:
                    frozen.add(record[1])
                success = True

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account = parts[1]
            amount = parse_amount(parts[2])
            if amount is not None:
                if verb == "open":
                    if account not in balances:
                        balances[account] = amount
                        history.append(("open", account))
                        success = True
                elif amount > 0 and account in balances:
                    old_balance = balances[account]
                    if verb == "deposit":
                        balances[account] += amount
                        history.append(("balance", account, old_balance))
                        success = True
                    elif account not in frozen and old_balance >= amount:
                        balances[account] -= amount
                        history.append(("balance", account, old_balance))
                        success = True

        elif verb == "transfer" and len(parts) == 4:
            source, target = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (amount is not None and amount > 0 and source != target
                    and source in balances and target in balances
                    and source not in frozen and balances[source] >= amount):
                history.append(
                    ("transfer", source, target, balances[source], balances[target])
                )
                balances[source] -= amount
                balances[target] += amount
                success = True

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account in balances:
                if verb == "freeze" and account not in frozen:
                    frozen.add(account)
                    history.append(("freeze", account))
                    success = True
                elif verb == "unfreeze" and account in frozen:
                    frozen.remove(account)
                    history.append(("unfreeze", account))
                    success = True

        if not success:
            rejected.append(index)

    return balances, rejected
